package com.devorld.auth; import jakarta.persistence.*;
@Entity @Table(name="DEVORLD_USERS") public class AppUser { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="FULL_NAME",nullable=false) private String fullName; @Column(name="GENDER") private String gender; @Column(name="EMAIL",nullable=false,unique=true) private String email; @Column(name="MOBILE") private String mobile; @Column(name="ADDRESS") private String address; @Column(name="PASSWORD_HASH",nullable=false) private String passwordHash; @Column(name="ROLE",nullable=false) private String role="CUSTOMER"; public Long getId(){return id;} public String getFullName(){return fullName;} public String getEmail(){return email;} public String getPasswordHash(){return passwordHash;} public String getRole(){return role;} public void setFullName(String v){fullName=v;} public void setGender(String v){gender=v;} public void setEmail(String v){email=v;} public void setMobile(String v){mobile=v;} public void setAddress(String v){address=v;} public void setPasswordHash(String v){passwordHash=v;} }
